const arr = [10, 20, 30];
const iter = arr[Symbol.iterator]();

const paso1 = iter.next();
const paso2 = iter.next();
const paso3 = iter.next();
const paso4 = iter.next(); // Agotado

const v1 = paso1.value;
const v2 = paso2.value;
const v3 = paso3.value;
const ultimoDone = paso4.done;

console.log(v1, v2, v3);
console.log('done:', ultimoDone);

function crearRango(inicio, fin, paso = 1) {
  return {
    [Symbol.iterator]() {
      let actual = inicio;
      return {
        next() {
          const terminado = paso > 0 ? actual > fin : actual < fin;
          if (terminado) return { value: undefined, done: true };
          const value = actual;
          actual += paso;
          return { value, done: false };
        }
      };
    }
  };
}

const r1 = [...crearRango(1, 5)];
const r2 = [...crearRango(0, 10, 2)];
const r3 = [...crearRango(5, 1, -1)];

console.log(r1);
console.log(r2);
console.log(r3);

function crearPaginador(datos, tamanioPagina) {
  return {
    [Symbol.iterator]() {
      let indice = 0;
      return {
        next() {
          if (indice >= datos.length) return { value: undefined, done: true };
          const pagina = datos.slice(indice, indice + tamanioPagina);
          indice += tamanioPagina;
          return { value: pagina, done: false };
        }
      };
    }
  };
}

const paginas = [...crearPaginador([1, 2, 3, 4, 5, 6, 7], 3)];
const totalPaginas = paginas.length;
const primera = paginas[0];
const ultima = paginas[2];

console.log('Total páginas:', totalPaginas);
console.log('Primera:', primera);
console.log('Última:', ultima);
